mapper.select:
SELECT r.RESERVATION_ID, r.USER_ID, r.ASSET_ID, r.START_TIME, r.END_TIME, r.PURPOSE, r.STATUS, r.ADDRESS, r.ADDRESS_STATE, r.ADDRESS_CITY, r.CREATED_AT, r.COMPLETED_AT, r.USAGE_DURATION, r.ADMIN_ID, r.IS_REJECTED, r.REJECT_REASON, a.NAME as ASSET_NAME, a.CATEGORY as ASSET_CATEGORY, a.COMPANY as ASSET_COMPANY, a.IMAGE as ASSET_IMAGE, u.name as ADMIN_NAME FROM RESERVATION r JOIN ASSET a ON r.ASSET_ID = a.ASSET_ID LEFT JOIN USERS u ON r.ADMIN_ID = u.USER_ID WHERE r.USER_ID = #{userId} AND a.IS_DELETED = 'N'
AND (r.COMPLETED_AT IS NOT NULL)
AND r.STATUS = 'CANCELLED'
AND r.IS_REJECTED = 'Y' AND r.REJECT_REASON != '사용자 취소'
AND r.STATUS = 'APPROVED' AND r.START_TIME <= SYSDATE AND r.END_TIME > SYSDATE AND r.COMPLETED_AT IS NULL
AND r.STATUS = #{status} AND (r.IS_REJECTED IS NULL OR r.IS_REJECTED = 'N')
AND r.START_TIME >= #{startDate}
AND r.END_TIME <= #{endDate}
AND a.CATEGORY = #{category}
ORDER BY r.CREATED_AT DESC

SELECT r.RESERVATION_ID, r.USER_ID, r.ASSET_ID, r.START_TIME, r.END_TIME, r.PURPOSE, r.STATUS, r.ADDRESS, r.ADDRESS_STATE, r.ADDRESS_CITY, r.CREATED_AT, r.COMPLETED_AT, r.USAGE_DURATION, r.ADMIN_ID, r.IS_REJECTED, r.REJECT_REASON, a.NAME as ASSET_NAME, a.CATEGORY as ASSET_CATEGORY, a.COMPANY as ASSET_COMPANY, a.IMAGE as ASSET_IMAGE, u.name as ADMIN_NAME FROM RESERVATION r JOIN ASSET a ON r.ASSET_ID = a.ASSET_ID LEFT JOIN USERS u ON r.ADMIN_ID = u.USER_ID WHERE r.USER_ID = #{userId} AND a.IS_DELETED = 'N' AND r.STATUS IN ('APPROVED', 'COMPLETED') AND (r.IS_REJECTED IS NULL OR r.IS_REJECTED = 'N') AND ( r.COMPLETED_AT IS NOT NULL OR (r.START_TIME <= SYSDATE AND r.END_TIME > SYSDATE) OR r.END_TIME <= SYSDATE )
AND r.START_TIME >= #{startDate}
AND r.END_TIME <= #{endDate}
AND a.CATEGORY = #{category}
AND (r.COMPLETED_AT IS NOT NULL )
AND r.START_TIME <= SYSDATE AND r.END_TIME > SYSDATE AND r.COMPLETED_AT IS NULL
AND r.END_TIME < SYSDATE AND r.COMPLETED_AT IS NULL
ORDER BY r.START_TIME DESC
